import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"觀","description":"東坡易傳 - 觀","frontmatter":{"title":"觀","description":"東坡易傳 - 觀"},"headers":[],"relativePath":"classics/dongpo/021.md","filePath":"classics/dongpo/021.md"}'),o={name:"classics/dongpo/021.md"};function r(n,p,c,_,i,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="觀" tabindex="-1">觀 <a class="header-anchor" href="#觀" aria-label="Permalink to “觀”">​</a></h1><p>“觀”：盥而不薦，有孚顒若。</p><p>《彖》曰：大觀在上，順而巽，中正以觀天下。“觀，盥而不薦，有孚顒若”，下觀而化也。觀天之神道而四時不忒，聖人以神道設教，而天下服矣。</p><p>無器而民趨，不言而物喻者，“觀”之道也。聖人以神道設教，則賞爵刑罰有設而不用者矣。寄之宗廟，則“盥而不薦”者也。盥者以誠，薦者以味。</p><p>象曰：風行地上，“觀”；先王以省方，觀民設教。</p><p>初六：童觀，小人無咎，君子吝。象曰：“初六童觀”，小人道也。</p><p>大觀在上，故四陰皆以尚賓為事。初六，童而未仕者也，急於用，以自衒賈，惟器小而夙成者為無咎，君子則吝矣。</p><p>六二：窺觀，利女貞。象曰：“窺觀”“女貞”，亦可醜也。</p><p>六二遠且弱，宜處而未宜實者也。譬之於女，利貞而不利行者也。苟以此為觀，則是女不待禮而窺以相求，貞者之所醜也。</p><p>六三：觀我生，進退。象曰：“觀我生進退”，未失道也。</p><p>六三，上下之際也。故當自觀其生，以卜進退。夫欲知其君，則觀其民；故我之生，則君之所為也。知君之所為，則進退決矣。進退在我，故未失道也。</p><p>六四：觀國之光，利用賓於王。象曰：“觀國之光”，尚賓也。</p><p>進退之決在六三，故自三以下，利退而不利進；自三以上，利進而不利退。進至於四，決不可退矣，故“利用賓於王”。</p><p>九五：觀我生，君子無咎。象曰：“觀我生”，觀民也。</p><p>上九：觀其生，君子無咎。象曰：“觀其生”，志未平也。</p><p>此二觀，所自言之者不同，其實一也。觀我生，讀如“觀兵”之“觀”；“觀其生”，讀如“觀魚”之“觀”。九五以其至顯觀之於民，以我示民，故曰“觀我生”。上九處於至高而下觀之，自民觀我，故曰“觀其生”。今夫乘車於道，負者皆有不平之心，聖人以其一身擅天下之樂，厚自奉以觀示天下而天下不怨，夫必有以大服之矣。吾以吾可樂之生而觀之人，人亦觀吾生可樂，則天下之爭心將自是而起，故曰“君子無咎”。君子而後無咎，難乎其無咎也！</p>',16)])])}const f=a(o,[["render",r]]);export{m as __pageData,f as default};
